<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/core/session.php';require_once __DIR__.'/../classes/identity/User.php';require_once __DIR__.'/../classes/system/SystemSettings.php';require_once __DIR__.'/../classes/identity/AccountSecurity.php';
if(isLoggedIn()){header('Location: ../dashboard/layout.php');exit;}header('Cache-Control: no-store');$_SESSION['register_csrf']=$_SESSION['register_csrf']??bin2hex(random_bytes(24));$error='';$grades=[];$enabled=false;
try{$db=(new Database())->getConnection();$enabled=(new SystemSettings($db))->isEntranceExamEnabled();$grades=$db->query('SELECT DISTINCT g.name FROM academic_grade_levels g JOIN academic_departments d ON d.id=g.department_id WHERE g.is_active=1 AND d.is_active=1 ORDER BY g.sort_order,g.name')->fetchAll(PDO::FETCH_COLUMN);}catch(Throwable $ex){$error='Registration is temporarily unavailable. Please try again later.';}
if($_SERVER['REQUEST_METHOD']==='POST')try{
 if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['register_csrf'],$_POST['csrf']))throw new RuntimeException('Reload this page before registering.');if(!$enabled)throw new RuntimeException('Entrance exam registration is currently closed. Please contact the Guidance Office.');
 $names=[];foreach(['first_name','middle_name','last_name'] as $f){$v=$_POST[$f]??'';if(!is_string($v))throw new RuntimeException('Enter valid names.');$v=preg_replace('/\s+/u',' ',trim($v));if(mb_strlen($v)>($f==='middle_name'?100:50)||($f!=='middle_name'&&$v===''))throw new RuntimeException('First and last names are required, up to 50 characters.');$names[$f]=$v;}
 $email=EmailIdentity::normalize($_POST['email']??'');EmailIdentity::requireAvailable($db,$email);$password=AccountSecurity::password($_POST['password']??'');if($password!==($_POST['confirm_password']??''))throw new RuntimeException('The passwords do not match.');
 $type=$_POST['student_type']??'';$grade=$_POST['grade_level_applying']??'';if(!in_array($type,['new','transfer'],true)||!in_array($grade,$grades,true))throw new RuntimeException('Choose a valid applicant type and grade / year level.');if($type==='new'&&!in_array($grade,['Grade 1','Grade 7','Grade 11','1st Year College'],true))throw new RuntimeException('Choose a new-student entry level. Use Transferee when applying to another level.');
 $user=new User($db);foreach($names as $f=>$v)$user->$f=$v?:null;$user->email=$email;$user->password=$password;$user->role='examinee';$user->grade_level_applying=$grade;$user->examinee_type=$type==='new'?'New Student':'Transferee';$user->student_id=null;$user->position=null;
 $db->beginTransaction();if(!$user->register())throw new RuntimeException('Your account could not be created. Please try again.');$accountId=(int)$db->lastInsertId();require_once __DIR__.'/../classes/notifications/SubmissionNotifications.php';SubmissionNotifications::examineeAccount($db,$accountId);$db->commit();$_SESSION['auth_notice']='Your examinee account is ready. Sign in with your email to choose an entrance exam schedule.';$_SESSION['register_csrf']=bin2hex(random_bytes(24));header('Location: login.php');exit;
}catch(Throwable $ex){if(isset($db)&&$db instanceof PDO&&$db->inTransaction())$db->rollBack();$error=$ex instanceof PDOException?'Your account could not be created. Check your details or use an existing account.':$ex->getMessage();}
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$v=static fn($k)=>is_string($_POST[$k]??null)?$_POST[$k]:'';?>
