<form method="post" class="ac-form"><input type="hidden" name="csrf" value="<?=$e($_SESSION['register_csrf'])?>"><div class="ac-form-grid">
<?php foreach(['first_name'=>'First name *','last_name'=>'Last name *','middle_name'=>'Middle name (optional)'] as $k=>$label):?><label><?=$label?><input name="<?=$k?>" value="<?=$e($v($k))?>" maxlength="<?=$k==='middle_name'?100:50?>" <?=$k==='middle_name'?'':'required'?> autocomplete="<?=['first_name'=>'given-name','last_name'=>'family-name','middle_name'=>'additional-name'][$k]?>"></label><?php endforeach;?>
<label>Email address *<input type="email" name="email" autocomplete="email" maxlength="100" value="<?=$e($v('email'))?>" required><small>Each email can belong to only one account.</small></label><label>Applicant type *<select name="student_type" id="applicant-type" required><option value="">Choose type</option><option value="new" <?=$v('student_type')==='new'?'selected':''?>>New student</option><option value="transfer" <?=$v('student_type')==='transfer'?'selected':''?>>Transferee</option></select></label><label>Applying for *<select name="grade_level_applying" id="entry-level" required><option value="">Choose grade / year</option><?php foreach($grades as $g):?><option value="<?=$e($g)?>" <?=$v('grade_level_applying')===$g?'selected':''?>><?=$e($g)?></option><?php endforeach;?></select></label><label>Password *<input type="password" name="password" autocomplete="new-password" minlength="8" maxlength="72" required><small>Use 8–72 characters.</small></label><label>Confirm password *<input type="password" name="confirm_password" autocomplete="new-password" minlength="8" maxlength="72" required></label></div><button class="ac-primary">Create examinee account</button></form><script>(()=>{const type=document.getElementById('applicant-type'),grade=document.getElementById('entry-level');function update(){for(const o of grade.options){o.hidden=o.disabled=!!o.value&&type.value==='new'&&!['Grade 1','Grade 7','Grade 11','1st Year College'].includes(o.value);}if(grade.selectedOptions[0]?.disabled)grade.value='';}type.addEventListener('change',update);update();})();</script><?php endif;?>
